47	const computeParents = (
48	  prefix: string,
49	  node: TreeNode,
50	): {
51	  parents: TreeParents;
52	  leaves: Array<string>;
53	  tests: Array<[string, TreeNode]>;
54	  lowestParents: Array<LowestNode>;
55	} => {
56	  let parents: TreeParents = {};
57	  const leaves: Array<string> = [];
58	  const tests: Array<[string, TreeNode]> = [];
59	  const lowestParents: Array<LowestNode> = [];
60	
61	  if (node?.obs && Array.isArray(node.obs) && node.obs.length > 0) {
62	    // This is a leaf test (Test concept) - has obs data
63	    leaves.push(node.flatName);
64	    tests.push([node.flatName, node]);
65	  } else if (node?.subSets && Array.isArray(node.subSets) && node.subSets.length > 0) {
66	    // parent category - recursively process children
67	
68	    const childResults = node.subSets
69	      .map((subNode) => {
70	        if (subNode) {
71	          // Don't add the current node's display name as a prefix
72	          // This prevents creating "Bloodwork-Hematology-..." names
73	          return computeParents(prefix, subNode);
74	        }
75	        return null;
76	      })
77	      .filter(Boolean);
78	
79	    // Merge results from children
80	    childResults.forEach((result) => {
81	      if (result) {
82	        parents = { ...parents, ...result.parents };
83	        leaves.push(...result.leaves);
84	        tests.push(...result.tests);
85	        lowestParents.push(...result.lowestParents);
86	      }
87	    });
88	
89	    // Check if this parent should be added to lowestParents
90	    // A parent should be in lowestParents if it has children with actual data
91	    const hasChildrenWithData = node.subSets.some((subNode) => subNode?.hasData);
